function extraResource(label:string):Resource|undefined {
 const n=label.toLowerCase();
 if(n.includes('linux journey')) return R.journey;
 if(n.includes('linux foundation')) return R.linux;
 if(n.includes('networking basics')) return R.netacad;
 if(n.includes('packet tracer')) return R.packet;
 if(n.includes('terraform')&&(n.includes('gcp')||n.includes('google')||n.includes('azure')||n.includes('cloud'))) return R.terraformAll;
 if(n.includes('terraform')) return R.terraform;
 if(n.includes('kubernetes')) return R.k8sIntro;
 if(n.includes('docker')) return R.docker;
 if(n.includes('github skills')) return R.skills;
 if(n.includes('powershell')) return R.powershell;
 if(n.includes('freecodecamp')) return R.freecode;
 if(n.includes('postgres')) return R.postgres;
 if(n.includes('ubuntu')) return R.ubuntu;
 if(n.includes('python')) return R.python;
 if(n.includes('fastapi')) return R.api;
 if(n.includes('portswigger')) return R.portswigger;
 if(n.includes('owasp')) return R.owasp;
 if(n.includes('prometheus')) return R.prometheus;
 if(n.includes('grafana')) return R.grafana;
 if(n.includes('finops')) return R.finops;
 if(n.includes('google cloud')||n.includes('gcp')) return R.gcp;
 if(n.includes('azure')||n.includes('microsoft learn')) return R.azure;
 if(n.includes('well-architected')) return R.awsArch;
 if(n.includes('aws workshop')) return R.awsWorkshop;
 if(n.includes('aws')) return R.awsEssentials;
 if(n.includes('sre')) return R.sre;
 if(n.includes('git')) return R.git;
 return undefined;
}
export const curriculum: Module[] = normalizedRows.map((r,i) => {
 const [title,description,stage,prerequisites,skills,hours,lessonRows,lab,review,projectTitle,architecture,deliverables,acceptance,certifications,tags,supplemental] = r;
 const lessons = lessonRows.map((line,j)=>{ const [lt,ld,resourceKey] = line.split('|'); const res = resourceMap[resourceKey]; if(!res) throw new Error(`Recurso não mapeado: ${String(resourceKey)} (${title}: ${lt})`); return {id:`m${i+1}-l${j+1}`,title:lt,description:ld,minutes:Math.max(20,Math.round(hours*60*.3/lessonRows.length)),resources:[res],practice:ld,check:[`Concluir uma evidência verificável de: ${lt.toLowerCase()}.`,'Registrar comandos, decisões e resultado esperado no README do projeto.']}; });
 const resources=[...new Map([...lessons.flatMap(l=>l.resources),...(supplemental||[]).map(extraResource).filter((x):x is Resource=>!!x)].map(resource=>[resource.url,resource])).values()];
 return {id:`m${i+1}`,number:i+1,title,stage,level:i<7?'Fundamentos':i<12||i===17?'Intermediário':'Avançado',description,objective:`${description} Objetivo profissional: ${stage==='Fundamentos'?'base para Cloud Support e suporte técnico cloud.':stage==='Intermediário'?'operar e automatizar workloads cloud com segurança.':'projetar, proteger e operar plataformas cloud em produção.'}`,prerequisites,skills,hours,lessons,resources,lab,review,project:{title:projectTitle,architecture,deliverables,acceptance},mastery:acceptance,certifications,tags:[...new Set([...tags,...skills.flatMap(s=>s.toLowerCase().split(/[ ,/]+/)).filter(Boolean)])]};
});

