export const resourceCatalog = [...new Map(curriculum.flatMap(m=>m.resources).map(x=>[x.url,x])).values()];
export function validateCurriculum(): string[] {
 const errors:string[]=[]; const ids=new Set(curriculum.map(m=>m.id));
 curriculum.forEach(m=>{ if(!m.title||!m.lessons.length) errors.push(`${m.id}: título/aulas ausentes`); m.prerequisites.forEach(p=>{if(p!=='Nenhum'&&p!=='Todos os módulos anteriores'&&!allTitles.includes(p)) errors.push(`${m.id}: pré-requisito desconhecido ${p}`)}); m.lessons.forEach(l=>l.resources.forEach(x=>{try{new URL(x.url); }catch{errors.push(`${l.id}: URL inválida`)}})); });
 if(ids.size!==curriculum.length) errors.push('IDs de módulo duplicados'); return errors;
}
